from __future__ import annotations

import json
from dataclasses import dataclass
from enum import Enum


@dataclass(frozen=True)
class Binding:
    keys: str
    """As shown and matched: modifiers then the key, joined
    by "+", eg "Alt+F", "Ctrl+Enter", "Escape"."""
    where: str
    what: str
    also: str = ""
    """A second key for the same thing, matched as `keys` is (panes.js), eg "Alt+Enter"."""


class Shortcut(Enum):
    # Handled by assets/panes.js (window.SHORTCUTS).
    FULL_SCREEN = Binding(
        "Alt+F",
        "result, pane",
        "Full screen: float the result you are in, else fill with your pane; the debug panel while it is open",
    )
    CLOSE = Binding("Escape", "floating result, menu, keybindings, full-screen debug log", "Close it")
    TOGGLE_CHAT = Binding("Alt+A", "anywhere", "Show or hide the AI chat pane")
    TOGGLE_RESULTS = Binding("Alt+R", "anywhere", "Show or hide the Results pane")
    TOGGLE_PYTHON = Binding("Alt+J", "anywhere", "Show or hide the Python (Jupyter) pane")
    # Alt+` as VS Code's Ctrl+` (the app's keys are Alt); matched by position: Shift makes it ~
    # also Alt+Enter, as Omarchy's SUPER+Enter opens a terminal (with Shift: full screen)
    TOGGLE_TERMINAL = Binding(
        "Alt+`", "anywhere", "Show or hide the Terminal pane: a shell on this machine", also="Alt+Enter"
    )
    TOGGLE_VARIABLES = Binding(
        "Alt+V",
        "anywhere",
        "Show or hide the Variables pane: the Python names you have (r1, q1, your own), to see and clear",
    )
    TOGGLE_PYTHON_VARIABLES = Binding(
        "Alt+Ctrl+J",
        "anywhere",
        "Show the Python and Variables panes together (opens whichever is hidden); hide both when both are open",
    )
    # Alt+W as Omarchy's SUPER+W closes a window; also from inside the Terminal (terminal.py)
    CLOSE_ALL = Binding(
        "Alt+W", "anywhere", "Close every panel (and the help or debug panel): only the desktop's background shows"
    )
    # Between the panes shown, as Omarchy's SUPER+arrows move between windows. The active pane
    # (assets/panes.js) is where the cursor is; opening a pane makes it the active one.
    NEXT_PANE = Binding("Alt+ArrowRight", "anywhere", "Go to the next pane shown: the cursor moves into it")
    PREV_PANE = Binding("Alt+ArrowLeft", "anywhere", "Go to the previous pane shown: the cursor moves into it")
    # One pane full screen, from anywhere (shown even if hidden); the same key
    # again restores the layout. Alt+F does it for the pane (or result) you are in.
    ZOOM_CHAT = Binding("Alt+Shift+A", "anywhere", "Full screen the AI chat pane (again: restore panes)")
    ZOOM_RESULTS = Binding("Alt+Shift+R", "anywhere", "Full screen the Results pane (again: restore panes)")
    ZOOM_PYTHON = Binding("Alt+Shift+J", "anywhere", "Full screen the Python pane (again: restore panes)")
    ZOOM_VARIABLES = Binding("Alt+Shift+V", "anywhere", "Full screen the Variables pane (again: restore panes)")
    ZOOM_TERMINAL = Binding(
        "Alt+Shift+`", "anywhere", "Full screen the Terminal pane (again: restore panes)", also="Alt+Shift+Enter"
    )
    HELP = Binding("Alt+H", "anywhere", "Show or hide this help")
    PALETTE = Binding(
        "Alt+P", "anywhere", "Command palette: run anything by name, eg add a widget (type to filter, arrows, Enter)"
    )
    # Handled by assets/keys.js.
    KEYS = Binding("Alt+K", "anywhere", "Show or hide the keybindings list (type to filter)")
    DEBUG = Binding("Alt+D", "anywhere", "Show or hide the debug log: every request the app made, memory")
    # Handled by the chat box (a form textarea).
    SEND = Binding("Enter", "chat", "Send")
    NEW_LINE = Binding("Shift+Enter", "chat", "New line")
    # Handled by assets/history.js, as a terminal's history.
    CHAT_HISTORY = Binding(
        "ArrowUp",
        "chat (empty box)",
        "The last message you sent, then the ones before; ArrowDown goes forward again",
    )
    # Handled by the cell editor's keymap (cell_editor.jsx, given by codemirror_keys).
    RUN_AND_ADVANCE = Binding("Shift+Enter", "cell", "Run and go to the next cell")
    RUN = Binding("Ctrl+Enter", "cell", "Run")
    COMPLETE = Binding("Tab", "cell, table SQL, SmashDb console", "Complete")
    # The Python console has no buttons for these: it is worked from the keyboard, from the
    # cell the cursor is in (the palette has Run all / Clear
    # outputs / New cell for when it is in none).
    RUN_ALL = Binding("Ctrl+Shift+Enter", "cell", "Run all cells, top to bottom")
    CLEAR_OUTPUTS = Binding("Alt+Z", "cell", "Clear every cell's output")
    # Alt+N (new); it was Alt+Enter until that became the Terminal's second key
    CELL_BELOW = Binding("Alt+N", "cell", "Add a cell below this one and go to it")
    DELETE_CELL = Binding("Alt+Backspace", "cell", "Delete this cell (the cursor goes to the one above)")
    CELL_UP = Binding("Alt+ArrowUp", "cell", "Go to the cell above")
    CELL_DOWN = Binding("Alt+ArrowDown", "cell", "Go to the cell below")
    # Handled by inline_edit.jsx, in a cell and the SmashDb console's SQL box; outside an
    # editor, in a result with a tool form, by assets/panes.js (it
    # clicks the result's AI button, render.ai_toggle).
    INLINE_EDIT = Binding(
        "Alt+I",
        "cell, SmashDb console, result with inputs, terminal",
        " ".join(
            [
                "Inline chat, knowing the chat so far: ask AI to write or change the code",
                "(the selection, else all; Tab accepts, Esc discards), to fill a result's inputs",
                "(you run them; Esc puts the old ones back), or to write a command at the",
                "Terminal's prompt (you run it). The key again closes it",
            ]
        ),
    )
    # Handled by the SQL box (sql_editor.jsx): a table view's, and a SmashDb console's editor.
    RUN_SQL = Binding(
        "Ctrl+Enter",
        "table SQL, SmashDb console",
        "Run the query (polars SQL; a table's own box queries it as self; a selection runs alone)",
    )
    # A mouse action, listed for the help panel.
    TAB_MENU = Binding("Right-click", "result tab", "Show in Chat, Close, Close Others, Close to the Right, Close All")

    @property
    def keys(self) -> str:
        return self.value.keys

    @property
    def shown(self) -> str:
        """Its keys as listed for people: both when it has two, eg "Alt+` / Alt+Enter"."""
        return f"{self.keys} / {self.value.also}" if self.value.also else self.keys

    def hint(self, text: str) -> str:
        """A tooltip with the shortcut, eg "Full screen (Alt+F)"."""
        return f"{text} ({self.keys})"


# What panes.js and keys.js match on keydown.
BROWSER_SHORTCUTS = (
    Shortcut.FULL_SCREEN,
    Shortcut.CLOSE,
    Shortcut.TOGGLE_CHAT,
    Shortcut.TOGGLE_RESULTS,
    Shortcut.TOGGLE_PYTHON,
    Shortcut.TOGGLE_VARIABLES,
    Shortcut.TOGGLE_TERMINAL,
    Shortcut.TOGGLE_PYTHON_VARIABLES,
    Shortcut.CLOSE_ALL,
    Shortcut.NEXT_PANE,
    Shortcut.PREV_PANE,
    Shortcut.ZOOM_CHAT,
    Shortcut.ZOOM_RESULTS,
    Shortcut.ZOOM_PYTHON,
    Shortcut.ZOOM_VARIABLES,
    Shortcut.ZOOM_TERMINAL,
    Shortcut.HELP,
    Shortcut.PALETTE,
    Shortcut.KEYS,
    Shortcut.DEBUG,
    # an editor's own keys (inline_edit.jsx): panes.js needs them to run one from the palette,
    # and handles this one itself in a result with a tool form
    Shortcut.INLINE_EDIT,
)


def shortcuts_script() -> str:
    """JS that sets window.SHORTCUTS for panes.js, eg {"FULL_SCREEN":
    "Alt+F", "CLOSE": "Escape"}.
    """
    also = {s.name: s.value.also for s in BROWSER_SHORTCUTS if s.value.also}
    return " ".join(
        [
            f"window.SHORTCUTS = {json.dumps({s.name: s.keys for s in BROWSER_SHORTCUTS})};",
            # second keys (Binding.also), by the same names: panes.js matches either
            f"window.SHORTCUTS_ALSO = {json.dumps(also)};",
        ]
    )


def codemirror_key(shortcut: Shortcut) -> str:
    """CodeMirror's spelling of a binding: "Ctrl+Enter" -> "Mod-Enter" (Cmd on a Mac), "Alt+I"
    -> "Alt-i", "Alt+Shift+A" -> "Alt-Shift-a" (CodeMirror wants
    the letter in lower case, Shift named apart).
    """
    *mods, key = shortcut.keys.split("+")
    return "-".join(["Mod" if mod == "Ctrl" else mod for mod in mods] + [key.lower() if len(key) == 1 else key])


def sql_keys() -> dict[str, str]:
    """The SQL box's keymap, by the prop names sql_editor.jsx reads."""
    return {
        "run": codemirror_key(Shortcut.RUN_SQL),
        "complete": codemirror_key(Shortcut.COMPLETE),
        "inlineEdit": codemirror_key(Shortcut.INLINE_EDIT),
    }


def codemirror_keys() -> dict[str, str]:
    """The cell editor's keymap, by the prop names cell_editor.jsx reads."""
    return {
        "run": codemirror_key(Shortcut.RUN),
        "runAndAdvance": codemirror_key(Shortcut.RUN_AND_ADVANCE),
        "complete": codemirror_key(Shortcut.COMPLETE),
        "inlineEdit": codemirror_key(Shortcut.INLINE_EDIT),
        "runAll": codemirror_key(Shortcut.RUN_ALL),
        "clearOutputs": codemirror_key(Shortcut.CLEAR_OUTPUTS),
        "cellBelow": codemirror_key(Shortcut.CELL_BELOW),
        "deleteCell": codemirror_key(Shortcut.DELETE_CELL),
        "cellUp": codemirror_key(Shortcut.CELL_UP),
        "cellDown": codemirror_key(Shortcut.CELL_DOWN),
    }
